struct ProFoldState {
    open: bool,
    phase: Slide,
    height: Rc<Cell<Pixels>>,
}

#[derive(IntoElement)]
struct ProFold {
    id: ElementId,
    open: bool,
    estimate: f32,
    parent_gap: f32,
    render: Box<dyn FnOnce() -> AnyElement>,
}

impl RenderOnce for ProFold {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let init_open = self.open;
        let est = self.estimate;
        let st = w.use_keyed_state(pro_eid(&self.id, "fold"), cx, |_, _| ProFoldState {
            open: init_open,
            phase: Slide::new(f32::from(init_open)),
            height: Rc::new(Cell::new(px(est))),
        });
        let (amount, h_cell) = st.update(cx, |s, cx| {
            if s.open != self.open {
                s.open = self.open;
                s.phase.duration(f32::from(self.open), 0.24, cx);
            }
            (s.phase.get(w, cx).clamp(0., 1.), s.height.clone())
        });

        if !self.open && amount <= 0.002 {
            return div().into_any_element();
        }
        let h = h_cell.get();
        let content = (self.render)();
        div()
            .mt(px(-self.parent_gap * (1. - amount)))
            .w_full()
            .flex_none()
            .when(amount < 0.998, |v| v.h(h * amount).overflow_hidden())
            .opacity(amount)
            .child(
                div()
                    .w_full()
                    .flex_none()
                    .on_children_prepainted(move |bounds, _, _| {
                        if let Some(b) = bounds.first()
                            && b.size.height > px(0.)
                        {
                            h_cell.set(b.size.height);
                        }
                    })
                    .child(content),
            )
            .into_any_element()
    }
}

/// Measured-height spring disclosure (`0.24s`) that retains natural height during exit.
pub fn pro_fold(
    id: impl Into<ElementId>,
    open: bool,
    estimate: f32,
    parent_gap: f32,
    render: impl FnOnce() -> AnyElement + 'static,
) -> AnyElement {
    ProFold {
        id: id.into(),
        open,
        estimate,
        parent_gap,
        render: Box::new(render),
    }
    .into_any_element()
}

struct ProPresenceState {
    open: bool,
    phase: Slide,
}

#[derive(IntoElement)]
struct ProPresenceLayer {
    id: ElementId,
    open: bool,
    open_secs: f32,
    close_secs: f32,
    render: Box<dyn FnOnce(f32) -> AnyElement>,
}

impl RenderOnce for ProPresenceLayer {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let init_open = self.open;
        let st = w.use_keyed_state(pro_eid(&self.id, "pres"), cx, |_, _| ProPresenceState {
            open: init_open,
            phase: Slide::new(f32::from(init_open)),
        });
        let amount = st.update(cx, |s, cx| {
            if s.open != self.open {
                s.open = self.open;
                let secs = if self.open {
                    self.open_secs
                } else {
                    self.close_secs
                };
                s.phase.duration(f32::from(self.open), secs, cx);
            }
            s.phase.get(w, cx).clamp(0., 1.)
        });
        if !self.open && amount <= 0.003 {
            return div().into_any_element();
        }
        (self.render)(amount)
    }
}

/// Animated presence (`0.0..=1.0`) for boolean-gated modals, popovers, drawers, and dirty-state bars.
///
/// Calls `render(amount)` while opening, open, or closing so both entrance and exit animate smoothly.
pub fn pro_presence(
    id: impl Into<ElementId>,
    open: bool,
    open_secs: f32,
    close_secs: f32,
    render: impl FnOnce(f32) -> AnyElement + 'static,
) -> AnyElement {
    ProPresenceLayer {
        id: id.into(),
        open,
        open_secs,
        close_secs,
        render: Box::new(render),
    }
    .into_any_element()
}

#[derive(IntoElement)]
struct ProModalAppear {
    id: ElementId,
    key: SharedString,
    scrim_alpha: f32,
    dialog: AnyElement,
}

impl RenderOnce for ProModalAppear {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let init_key = self.key.clone();
        let st = w.use_keyed_state(pro_eid(&self.id, "mappear"), cx, |_, inner_cx| {
            let mut clock = PhaseClock::default();
            clock.restart(inner_cx);
            (init_key, clock)
        });
        let t = st.update(cx, |s, cx| {
            if s.0 != self.key {
                s.0 = self.key.clone();
                s.1.restart(cx);
            }
            let age = s.1.time(0.22, w, cx);
            pro_ease((age / 0.22).clamp(0., 1.))
        });
        div()
            .size_full()
            .bg(hsla(0., 0., 0., self.scrim_alpha * t))
            .flex()
            .items_center()
            .justify_center()
            .p(px(16.))
            .child(
                div()
                    .relative()
                    .top(px(8. * (1. - t)))
                    .opacity(t)
                    .child(self.dialog),
            )
    }
}

/// Smooth entrance & step-morph wrapper for `Option`-gated modal dialogs (`220ms` scrim fade + `8px` dialog settle).
pub fn pro_modal_appear(
    id: impl Into<ElementId>,
    step_key: impl Into<SharedString>,
    scrim_alpha: f32,
    dialog: impl IntoElement,
) -> AnyElement {
    ProModalAppear {
        id: id.into(),
        key: step_key.into(),
        scrim_alpha,
        dialog: dialog.into_any_element(),
    }
    .into_any_element()
}

#[derive(IntoElement)]
struct ProToastBanner {
    toast: Option<(SharedString, Instant)>,
}

impl RenderOnce for ProToastBanner {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let Some((msg, started)) = self.toast else {
            return div().into_any_element();
        };
        let elapsed = started.elapsed().as_secs_f32();
        let lifetime = 2.40;
        if elapsed >= lifetime {
            return div().into_any_element();
        }
        let reduced = disabled_motion(cx);
        if !reduced {
            w.request_animation_frame();
        }
        let t = if reduced {
            1.0
        } else if elapsed < 0.20 {
            pro_ease(elapsed / 0.20)
        } else if elapsed > lifetime - 0.26 {
            1. - pro_ease((elapsed - (lifetime - 0.26)) / 0.26)
        } else {
            1.0
        };
        let p = ProPalette::get(cx);
        div()
            .absolute()
            .bottom(px(16. - 8. * (1. - t)))
            .right(px(16.))
            .opacity(t)
            .h(px(34.))
            .px(px(12.))
            .rounded(px(8.))
            .bg(if p.dark { rgb(0x232327) } else { rgb(0x18181b) })
            .border_1()
            .border_color(if p.dark {
                p.line_strong
            } else {
                hsla(0., 0., 1., 0.12)
            })
            .shadow_md()
            .flex()
            .items_center()
            .gap(px(7.))
            .text_size(px(12.5))
            .font_weight(FontWeight::MEDIUM)
            .text_color(rgb(0xffffff))
            .child(pro_icon(ProIcon::Check, 13., p.green))
            .child(msg)
            .into_any_element()
    }
}

/// Animated floating toast banner (`2.4s` window with smooth spring slide-in and fade-out).
pub fn pro_toast_banner(toast: Option<(SharedString, Instant)>) -> AnyElement {
    ProToastBanner { toast }.into_any_element()
}

#[cfg(test)]
mod tests {
    use super::{pro_ease, pro_mix_color};
    use gpui::{Hsla, Rgba, rgb, transparent_black};

    #[test]
    fn pro_ease_is_monotonic_and_clamped() {
        assert_eq!(pro_ease(-0.5), 0.0);
        assert_eq!(pro_ease(0.0), 0.0);
        assert_eq!(pro_ease(1.0), 1.0);
        assert_eq!(pro_ease(1.5), 1.0);
        let mut prev = 0.0;
        for step in 1..=20 {
            let y = pro_ease(step as f32 / 20.0);
            assert!(y >= prev, "expected monotonic increase at step {step}");
            prev = y;
        }
    }

    #[test]
    fn pro_mix_color_preserves_hue_when_fading_from_transparent() {
        let blue: Hsla = rgb(0x0190fe).into();
        let mid = Rgba::from(pro_mix_color(transparent_black(), blue, 0.5));
        let full = Rgba::from(blue);
        assert!((mid.a - 0.5).abs() < 0.01);
        assert!((mid.r - full.r).abs() < 0.02);
        assert!((mid.g - full.g).abs() < 0.02);
        assert!((mid.b - full.b).abs() < 0.02);
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Window-relative placement for transient surfaces.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Default, Clone)]
pub(crate) struct TriggerBounds(Rc<Cell<Bounds<Pixels>>>);
impl TriggerBounds {
    pub fn measure(&self) -> impl IntoElement {
        let saved = self.0.clone();
        canvas(move |b, _, _| saved.set(b), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }
    pub fn get(&self) -> Bounds<Pixels> {
        self.0.get()
    }
    /// Prefer below the trigger. Flip above when it leaves more room.
    pub fn place(
        &self,
        view: Size<Pixels>,
        height: Pixels,
        gap: Pixels,
    ) -> (Point<Pixels>, Anchor) {
        let b = self.get();
        if b.bottom() + gap + height > view.height - px(10.) && b.top() > view.height - b.bottom() {
            (point(b.left(), b.top() - gap), Anchor::BottomLeft)
        } else {
            (point(b.left(), b.bottom() + gap), Anchor::TopLeft)
        }
    }
}
